const APP_RELEASE="3e26d596b0440763";
import * as M from './data.js';
import {recipes,plate} from './catalogue.js';
import * as P from './planning.js';
import * as S from './shopping.js';
import {voiceFormHTML,bindFoodVoice} from './voice-form.js';
import {foodIcon,recipeArt} from './visual.js';
let foodVoice=null;
let settingsDraft=null;const excluded=new Set();const ingredientNames=[...new Set(recipes.flatMap(r=>r.ingredients.map(i=>i[0])))].sort((a,b)=>a.localeCompare(b,'es'));const ration=n=>S.countWord(n,'ración','raciones');
const {U,D}=M,c=M.context(new URL(location.href).searchParams.get("revision")==="ficticia"?"revision-ficticia":"cocina"),$=x=>document.getElementById(x),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const nav=[['inicio','home','Inicio'],['despensa','box','Despensa'],['recetas','pot','Qué cocino'],['compra','bag','Compra'],['hogar','people','Hogar']];
let homeId='',stop=null,state={home:null,lots:[],shop:[],receipts:[],server:false},page='inicio',search='',place='Todas',minutes=60,vegetarian=false,recipeTab='ready',pending=null,authBusy=false;
const raw=x=>{const {id,...data}=x;return data;},normal=s=>s.trim().toLocaleLowerCase('es').normalize('NFD').replace(/\p{Diacritic}/gu,'');
const shopLabels={open:'Pendiente',bought:'Comprado',incorporated:'Incorporado',removed:'Retirado'};let activeRecipe=null; const recipeServings={},foodFilters={value:'all'},operationLabels={add:'Alimento añadido',edit:'Lote editado',cook:'Cocinado',consume:'Consumo',discard:'Descarte',shopping:'Lista de compra',incorporate:'Compra incorporada'}; const foodKey=P.foodKey,sameFood=P.sameFood,canWrite=()=>!!state.home&&state.server&&navigator.onLine&&!releaseChanged;
const fmt=n=>new Intl.NumberFormat("es-ES",{maximumFractionDigits:6}).format(n);
const operationFoods=g=>[...new Set(state.receipts.filter(r=>r.group===g).map(r=>r.after?.name||r.before?.name).filter(Boolean))].join(", ");
const intro=(label,title,copy)=>`<div class="eyebrow">${label}</div><h1>${title}</h1><p class="intro">${copy}</p>`;
const button=(action,label,key='',secondary=false)=>`<button aria-label="${esc(action==='recipe'?'Ver receta: '+recipes.find(r=>r.id===key)?.name:action==='incorporate'?label+': '+state.shop.find(x=>x.id===key)?.name:action==='portion'?'Cambiar cantidades y lotes de '+(P.requirements(recipes.find(r=>r.id===activeRecipe.key),recipeServings[activeRecipe.key]||state.home.servings,state.lots,M.today())[Number(key)]?.name||'ingrediente'):action==='shop-bought'?'Solo marcar comprado: '+state.shop.find(x=>x.id===key)?.name:action==='remove'?'Retirar a '+state.home?.memberNames[key]:action==='undo'?'Revisar corrección de '+(operationLabels[state.receipts.find(r=>r.group===key)?.kind]||'operación')+' de '+operationFoods(key)+' a las '+state.receipts.find(r=>r.group===key)?.createdAt?.toDate().toLocaleTimeString('es-ES'):label)}" class="button ${secondary?'secondary':'coral'}" data-action="${action}" data-id="${esc(key)}">${label}</button>`;
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),6500);}
let releaseChanged=false;
let dialogOrigin=null;
function focusKey(el){return el?.id?{id:el.id}:el?.dataset?.action?{action:el.dataset.action,key:el.dataset.id}:el?.getAttribute?.('href')?{href:el.getAttribute('href')}:null;}
function resolveFocus(key){return !key?null:key.id?$(key.id):key.action?document.querySelector(`[data-action="${CSS.escape(key.action)}"][data-id="${CSS.escape(key.key||'')}"]`):Array.from(document.querySelectorAll(`a[href="${CSS.escape(key.href)}"]`)).find(el=>el.getClientRects().length);}
function open(html){foodVoice?.dispose();foodVoice=null;const active=document.activeElement,focusId=$('dialog').open&&$('dialog').contains(active)?active.id:'';if(!$('dialog').open)dialogOrigin=focusKey(active);$('dialog-content').innerHTML=html;const title=$('dialog-content').querySelector('h2');if(title){title.id='dialog-title';title.tabIndex=-1;$('dialog').setAttribute('aria-labelledby','dialog-title');}if(!$('dialog').open)$('dialog').showModal();(focusId&&$(focusId)||title||$('close-dialog')).focus();}
$('dialog').addEventListener('close',()=>{foodVoice?.dispose();foodVoice=null;pending=null;(resolveFocus(dialogOrigin)||$('content')).focus({preventScroll:true});});
$('dialog').addEventListener('cancel',e=>{if($('dialog').getAttribute('aria-busy')==='true')e.preventDefault();});
$('dialog').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=Array.from($('dialog').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex="0"]')).filter(el=>el.getClientRects().length),first=items[0],last=items.at(-1);if(!first)return;const current=document.activeElement;if((e.shiftKey&&current===first)||(!e.shiftKey&&current===last)){e.preventDefault();(e.shiftKey?last:first).focus();}else if(current.id==='dialog-title'){e.preventDefault();(e.shiftKey?last:first).focus();}});
$('close-dialog').onclick=()=>$('dialog').close();
function errorMessage(e){return ({'auth/invalid-credential':'El correo o la contraseña no son correctos.','auth/email-already-in-use':'Ese correo ya tiene una cuenta. Inicia sesión o recupera la contraseña.','auth/weak-password':'La contraseña debe tener al menos 6 caracteres.','auth/invalid-email':'Revisa el correo.','auth/too-many-requests':'Demasiados intentos. Espera antes de volver a probar.','permission-denied':'No se pudo guardar: revisa tu acceso al hogar y vuelve a cargar los datos.','unavailable':'Falta confirmación del servidor. Recupera la conexión y reintenta esta revisión; la operación no se repetirá.'})[e.code]||e.message||'No se ha podido completar la operación.';}
function authView(){return intro('TU HOGAR','Cocina a Tiempo','Organiza los alimentos y la compra con las personas de tu hogar.')+`<article class="hero"><div class="hero-copy"><h2>Lo bueno está<br>en tu despensa.</h2><p>Accede con tu correo. No necesitas una cuenta de ChatGPT.</p><a class="button secondary" href="maqueta">Explorar con datos ficticios →</a></div><div class="hero-art">${plate}</div></article><section class="panel"><h2>Entrar o crear cuenta</h2><form id="auth-form"><label>Correo<input id="email" type="email" autocomplete="email" required></label><label>Contraseña<input id="password" type="password" autocomplete="current-password" minlength="6" required></label><div class="dialog-actions"><button class="button coral" ${authBusy?'disabled':''}>Entrar</button><button class="button secondary" id="register" type="button" ${authBusy?'disabled':''}>Crear cuenta</button><button class="text-link" id="reset" type="button">Recuperar contraseña</button></div><p id="auth-message" role="alert"></p></form><p class="hint">El correo se utiliza para el acceso y la recuperación. Los alimentos se comparten con los miembros de tu hogar. No introduzcas alergias ni información de salud.</p>${inviteToken()?'<div class="notice prefer"><strong>Has abierto una invitación</strong>Entra o regístrate y revisa el hogar antes de aceptarla.</div>':''}</section>`;}
function setupView(){return intro('CONFIGURA TU HOGAR','Ya has entrado','Una cuenta puede pertenecer a un hogar.')+`<section class="panel"><form id="setup-form"><label>Tu nombre o alias<input id="alias" maxlength="40" required></label>${inviteToken()?'<p>Invitación recibida. El enlace es de un uso y caduca a los siete días.</p>':'<label>Nombre del hogar<input id="home-name" maxlength="60" required placeholder="Por ejemplo: Hogar del Olivo"></label>'}<button class="button coral">${inviteToken()?'Aceptar invitación':'Crear hogar'}</button><p id="setup-message" role="status"></p></form>${button('logout','Cerrar sesión','',true)}</section>`;}
function inviteToken(){return new URL(location.href).searchParams.get('invita')||'';}
async function loadAccount(){stop?.();stop=null;state={home:null,lots:[],shop:[],receipts:[],server:false};homeId='';settingsDraft=null;quickUndo=null;excluded.clear();if(!c.auth.currentUser){render();return;}try{const p=await D.getDocFromServer(M.profileRef(c));if(!p.exists()){render();return;}homeId=p.data().homeId;await D.getDocFromServer(M.homeRef(c,homeId));stop=M.watch(c,homeId,s=>{if(s.home&&state.home?.vegetarian!==s.home.vegetarian)vegetarian=!!s.home.vegetarian;if(s.home&&JSON.stringify(state.home?.excludedIngredients||[])!==JSON.stringify(s.home.excludedIngredients||[])){excluded.clear();for(const n of s.home.excludedIngredients||[])excluded.add(n);}state=s;render();},e=>{state.server=false;if(e.code==='permission-denied'){stop?.();stop=null;state.home=null;homeId='revocado';$('dialog').close();}render();toast(errorMessage(e));});}catch(e){homeId='revocado';render();toast(errorMessage(e));}}
function row(l){const fs=M.foodState(l),label=fs==='unknown'?'Fecha desconocida':fs==='expired'?'Caducado':fs==='preferPast'?'Preferente superado':fs==='today'?'Hoy':l.date.split('-').reverse().join('/');return `<div class="food-row"><span class="food-icon" aria-hidden="true">${foodIcon(l.name)}</span><div class="food-main"><strong>${esc(l.name)}</strong><small>${esc(l.place)}${P.ambiguous(l.name)?'<br>Indica fresco o conserva al editar.':''}</small></div><span class="food-amount">${fmt(l.qty)} ${l.unit}</span><span class="food-date"><span class="date-label ${fs==='expired'?'red':fs==='today'?'warning':''}">${label}</span><small>${esc(l.dateType)}</small></span>${page==='despensa'?`<div class="food-actions"><button class="text-link" aria-label="Consumir o desechar ${esc(l.name)}, ${esc(l.place)}, ${esc(l.date||'sin fecha')}" data-action="out" data-id="${l.id}">Consumir o desechar</button><button class="text-link" aria-label="Editar ${esc(l.name)}, ${esc(l.place)}, ${esc(l.date||'sin fecha')}" data-action="edit" data-id="${l.id}">Editar</button></div>`:''}</div>`;}
const nearDate=l=>{const end=new Date(M.today()+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+state.home.noticeDays);return !!l.date&&l.date>=M.today()&&l.date<=end.toISOString().slice(0,10);};

const available=(name,unit)=>P.available(state.lots,name,unit,M.today());
const scaled=r=>P.scaled(r,recipeServings[r.id]||state.home?.servings||2);
const missing=r=>P.missing(r,recipeServings[r.id]||state.home?.servings||2,state.lots,M.today());
const compare=(a,b)=>P.compareRecipes(a,b,{lots:state.lots,today:M.today(),noticeDays:state.home.noticeDays,servings:r=>recipeServings[r.id]||state.home.servings});
const allowed=r=>S.eligibleRecipe(r,{minutes,vegetarian,excluded:[...excluded]});
function recipeReason(forFeatured=false){if(recipes.some(r=>r.complete&&!allowed(r)&&(forFeatured?P.related(r,state.lots,M.today())>0:S.matchesRecipeTab(r,recipeTab,recipeServings[r.id]||state.home.servings,state.lots,M.today()))))return 'Los filtros de tiempo o preferencias están limitando los resultados: ocultan recetas que encajan con esta vista. Revisa los filtros para verlas.';if(!recipes.some(allowed))return 'Los filtros de tiempo o preferencia excluyen las recetas. Amplía los filtros para ver otras opciones.';if(!state.lots.some(l=>P.usable(l,M.today())))return 'No hay alimentos disponibles: la despensa está vacía o sus fechas ya han pasado. Puedes ver recetas y preparar la compra.';if(recipes.filter(allowed).some(r=>P.unitIssues(r,state.lots,M.today()).length))return 'Faltan ingredientes o cantidades suficientes. Algunos alimentos están registrados en unidades distintas de las recetas: revisa sus medidas; no se convierten automáticamente.';if(forFeatured)return 'Ningún alimento disponible coincide con los ingredientes y unidades de estas recetas. Revisa los nombres o consulta alternativas con compra.';return 'Las cantidades disponibles no completan una receta con estos filtros. Puedes ver qué falta para comprar.';}
function unitHelp(r){const issues=P.unitIssues(r,state.lots,M.today());return issues.length?`<p class="hint">Revisar medidas: ${issues.map(i=>`${esc(i.name)} está en ${i.registered.join('/')} y la receta pide ${i.unit}`).join('; ')}. Pesa o mide el alimento y edita el lote si corresponde; no se hace ninguna conversión.</p>`:'';}
function recipeSummary(r){const req=P.requirements(r,recipeServings[r.id]||state.home.servings,state.lots,M.today()),absent=req.filter(i=>i.state==='absent'),short=req.filter(i=>i.state==='insufficient'),pending=req.filter(i=>i.state==='pending'),parts=[];if(absent.length)parts.push('No tienes: '+absent.map(i=>i.name).join(', ')+'.');if(short.length)parts.push('Cantidad insuficiente: '+short.map(i=>i.name).join(', ')+'.');if(pending.length)parts.push('Cantidad pendiente de confirmar: '+pending.map(i=>i.name).join(', ')+'.');return parts.join(' ')||'Tienes cantidades suficientes para esta receta.';}
function homeView(){const end=new Date(M.today()+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+state.home.noticeDays);const soon=state.lots.filter(l=>l.qty>0&&l.date&&l.date>=M.today()&&l.date<=end.toISOString().slice(0,10)).sort((a,b)=>a.date.localeCompare(b.date));const alternatives=recipes.filter(allowed).filter(r=>soon.some(l=>sameFood(l.name,r.ingredients.find(([n])=>sameFood(n,l.name))?.[0]||''))).sort(compare);const expired=state.lots.filter(l=>l.qty>0&&M.foodState(l)==='expired');const r=P.featured(recipes.filter(allowed),{lots:state.lots,today:M.today(),noticeDays:state.home.noticeDays,servings:r=>recipeServings[r.id]||state.home.servings});return intro('COCINA A TIEMPO','Lo bueno está en tu despensa.','Aprovecha lo que tienes y elige qué cocinar hoy.')+`<section class="urgent-summary" aria-label="Alimentos que requieren revisión">${expired.length?`<div class="urgent-item urgent-expired"><strong>${S.countWord(expired.length,'lote caducado','lotes caducados')}</strong>${button('expired','Revisar caducados','',true)}</div>`:''}${soon.length?`<div class="urgent-item"><strong>${S.countWord(soon.length,'lote próximo a su fecha','lotes próximos a su fecha')}</strong>${button('near','Revisar próximos','',true)}</div>`:''}${!expired.length&&!soon.length?'<p>Sin caducados ni alimentos próximos a su fecha.</p>':''}</section>${r?`<article class="hero"><div class="hero-copy"><span class="eyebrow">PARA COCINAR HOY</span><h2>${r.name}</h2><p>${esc(recipeSummary(r))}</p><div class="meta"><span class="pill">${r.time} min</span><span class="pill">${ration(recipeServings[r.id]||state.home.servings)}</span></div>${button('recipe','Ver receta →',r.id)}</div><div class="hero-art">${recipeArt(r)}</div></article>`:`<section class="panel"><h2>No hay una receta destacada</h2><p>${recipeReason(true)}</p>${button('review-filters','Revisar filtros','',true)}${button('alternatives','Ver alternativas con compra','',true)}</section>`}${soon.length?`<section class="panel urgent-foods"><div class="heading-row"><h2>Primero, estos alimentos</h2><a href="#despensa" data-action="near" class="text-link">Revisar próximos</a></div><p class="hint">Hoy y los próximos ${state.home.noticeDays} días · Madrid.</p>${soon.map(row).join('')}</section>`:''}<div class="heading-row add-food-row"><span>Añade lo que quieras aprovechar</span>${button('add','+ Añadir alimento')}</div>${alternatives.filter(x=>x.id!==r?.id).length?`<section class="urgent-alternatives"><h2>Otras ideas para aprovechar lo próximo a su fecha</h2><p class="hint">Pueden necesitar revisar cantidades o comprar ingredientes. No se da por comprobado el peso de las piezas.</p><div class="cards">${alternatives.filter(x=>x.id!==r?.id).slice(0,3).map(recipeCard).join('')}</div></section>`:''}`;}
function pantry(){const list=state.lots.filter(l=>l.qty>0&&(place==='Todas'||place===l.place)&&normal(l.name).includes(normal(search))&&(foodFilters.value==='all'||(foodFilters.value==='near'?nearDate(l):M.foodState(l)===foodFilters.value)));return intro('TUS ALIMENTOS','Despensa','Cada compra conserva su lote y su fecha.')+`<div class="heading-row"><span class="hint">${S.countWord(list.length,'lote','lotes')}</span>${button('add','+ Añadir alimento')}</div><div class="toolbar"><input id="search" type="search" aria-label="Buscar alimento" placeholder="Buscar en la despensa" value="${esc(search)}"><select id="place-filter" aria-label="Filtrar por ubicación">${['Todas','Nevera','Congelador','Despensa'].map(p=>`<option ${p===place?'selected':''}>${p}</option>`).join('')}</select><select id="food-filter" aria-label="Filtrar por estado">${[['all','Todos los estados'],['expired','Caducados'],['near','Próximos a su fecha'],['preferPast','Consumo preferente superado'],['unknown','Fecha desconocida']].map(([v,label])=>`<option value="${v}" ${foodFilters.value===v?'selected':''}>${label}</option>`).join('')}</select></div><details class="date-help"><summary>Cómo interpretar las fechas</summary><p>Caducidad y consumo preferente son distintos. Ambas fechas superadas se excluyen de las recetas. La fecha desconocida no tiene prioridad. Revisa siempre el estado del alimento.</p></details><section class="panel">${list.map(row).join('')||'<p class="empty">No hay alimentos en esta vista.</p>'}</section>`;}
function recipeCard(r){const m=missing(r),req=P.requirements(r,recipeServings[r.id]||state.home.servings,state.lots,M.today()),priority=P.priority(r,state.lots,M.today(),state.home.noticeDays);return `<article class="recipe-card"><div class="recipe-art" aria-hidden="true">${recipeArt(r)}</div><div class="recipe-copy"><div class="eyebrow">${r.time} MIN · ${ration(recipeServings[r.id]||state.home.servings).toLocaleUpperCase("es")}</div><h3>${r.name}</h3>${priority.date?`<p class="priority">Prioridad: aprovecha alimentos con fecha ${priority.date.split('-').reverse().join('/')}.</p>`:''}<p>${m.length?'Falta: '+m.map(i=>`${fmt(i.qty)} ${i.unit} de ${i.name}`).join(', '):req.some(i=>i.state==='pending')?'Hay cantidades pendientes de confirmar.':'Tienes los ingredientes en cantidad suficiente.'}</p><p class="hint">${P.related(r,state.lots,M.today())?'Alimentos que tienes: '+scaled(r).filter(i=>state.lots.some(l=>sameFood(l.name,i.name)&&P.usable(l,M.today()))).map(i=>i.name).join(', '):'Necesita comprar todos los ingredientes'}.</p>${req.filter(i=>i.state==='pending').map(i=>`<p class="hint">${presentMessage(i)}</p>`).join('')}${button('recipe','Ver receta →',r.id,true)}</div></article>`;}
function cooking(){const list=recipes.filter(allowed).sort(compare).filter(r=>S.matchesRecipeTab(r,recipeTab,recipeServings[r.id]||state.home.servings,state.lots,M.today()));const hiddenMatches=recipes.some(r=>r.complete&&!allowed(r)&&S.matchesRecipeTab(r,recipeTab,recipeServings[r.id]||state.home.servings,state.lots,M.today()));return intro('IDEAS PARA HOY','Qué cocino','15 recetas para dos raciones de base, ajustables. Primero se muestran las que aprovechan alimentos próximos a su fecha.')+`<details id="recipe-preferences" class="preference-panel"><summary>Excluir ingredientes por preferencia${excluded.size?" · "+excluded.size:""}</summary><p class="hint">Preferencia para estas sugerencias. La administración guarda la preferencia compartida en Hogar. No introduzcas datos de salud: este filtro no protege frente a alergias reales.</p><div class="preference-options">${ingredientNames.map((n,index)=>`<label class="checkbox-line"><input id="exclude-${index}" type="checkbox" data-exclude="${esc(n)}" ${excluded.has(n)?"checked":""}>${esc(n)}</label>`).join("")}</div></details><div class="toolbar"><label>Tiempo <select id="minutes"><option value="60" ${minutes===60?'selected':''}>Hasta 60 minutos</option><option value="20" ${minutes===20?'selected':''}>Hasta 20 minutos</option></select></label><label class="checkbox-line"><input id="vegetarian" type="checkbox" ${vegetarian?'checked':''}>Vegetariana</label></div><div class="chips" role="group" aria-label="Disponibilidad de recetas"><button aria-pressed="${recipeTab==='ready'}" class="chip ${recipeTab==='ready'?'active':''}" data-action="tab" data-id="ready">Con lo que tengo</button><button aria-pressed="${recipeTab==='pending'}" class="chip ${recipeTab==='pending'?'active':''}" data-action="tab" data-id="pending">Por confirmar</button><button aria-pressed="${recipeTab==='missing'}" class="chip ${recipeTab==='missing'?'active':''}" data-action="tab" data-id="missing">Falta algo</button></div>${recipeTab==='pending'?'<p class="hint">Por confirmar incluye recetas con cantidades por revisar que también pueden necesitar comprar otros ingredientes. Cada tarjeta indica qué tienes y qué falta.</p>':''}<div class="cards">${list.map(recipeCard).join('')||`<section class="panel"><p>${hiddenMatches?'Los filtros de tiempo o preferencias están limitando los resultados: ocultan recetas que encajan con esta vista. Revisa los filtros para verlas.':recipeTab==='pending'?'No hay alimentos con cantidades pendientes de confirmar.':recipeTab==='ready'?recipeReason():'Ninguna receta necesita compra con estos filtros. Prueba Con lo que tengo o amplía los filtros.'}</p>${hiddenMatches?button('review-filters','Revisar filtros','',true)+button('clear-filters','Quitar filtros','',true):''}${recipeTab==='ready'?button('pending-recipes','Revisar cantidades','',true):''}${button(recipeTab==='ready'?'alternatives':'clear-filters',recipeTab==='ready'?'Ver alternativas con compra':'Ampliar filtros','',true)}</section>`}</div>`;}
let quickUndo=null;const quickBusy=new Set();
function shopping(){quickUndo=S.currentShoppingNotice(quickUndo,homeId,state.shop);const list=state.shop.filter(s=>['open','bought'].includes(s.status));return intro('LO QUE FALTA','Compra','Guarda lo adquirido en despensa revisando su cantidad, ubicación y fecha. «Solo marcar comprado» lo deja para completar después, sin aumentar existencias.')+`<div class="heading-row"><span class="hint">${S.countWord(list.length,'producto','productos')}</span>${button('shop-add','+ Añadir producto')}</div>${quickUndo?.home===homeId?`<aside class="notice" role="status"><strong>${esc(quickUndo.message)}</strong>${quickUndo.group?button('quick-undo','Deshacer',quickUndo.group,true):''}</aside>`:''}<section class="shopping-list">${list.map(s=>`<div class="shop-row ${s.status==='open'?'is-pending':''}" aria-busy="${quickBusy.has(s.id)}"><div class="food-main"><strong>${esc(s.name)}</strong><small>${fmt(s.qty)} ${s.unit} · ${shopLabels[s.status]}</small></div><div class="shop-actions">${button('incorporate',s.status==='open'?'Comprado → Guardar en despensa':'Guardar en despensa',s.id)}${s.status==='open'?button('shop-bought','Solo marcar comprado',s.id,true):'<span class="hint">Comprado · falta guardar en despensa</span>'}</div><div class="shop-secondary"><button class="text-link" aria-label="Editar ${esc(s.name)} de la compra" data-action="shop-edit" data-id="${s.id}">Editar cantidad</button><button class="text-link" aria-label="Retirar ${esc(s.name)} de la compra" data-action="shop-remove" data-id="${s.id}">Retirar</button></div></div>`).join('')||'<p class="empty">Tu lista está vacía.</p>'}</section>`;}
async function markBought(key){if(quickBusy.has(key))return;const item=state.shop.find(x=>x.id===key);if(!item||item.status!=='open')return;const before=raw(item),group=M.id();quickBusy.add(key);render();try{if(!canWrite())throw Error('Espera a recuperar la conexión antes de guardar.');const result=await M.commit(c,homeId,[{type:'shop',id:key,before,after:{...before,status:'bought'}}],{kind:'shopping',group});if(result.state==='review')quickUndo={home:homeId,target:key,version:state.shop.find(x=>x.id===key)?.version,message:item.name+': el producto ha cambiado. Actualiza la lista antes de marcarlo comprado.'};else quickUndo={home:homeId,target:key,version:before.version+1,group,expires:Date.now()+30*60000,message:item.name+': comprado, pendiente de guardar en despensa.'};}catch(err){quickUndo={home:homeId,message:errorMessage(err)};}finally{quickBusy.delete(key);render();}}
async function undoMarked(group){const lock='undo-'+group;if(quickBusy.has(lock))return;quickBusy.add(lock);try{if(!canWrite())throw Error('Espera a recuperar la conexión antes de deshacer.');const records=await D.getDocs(D.query(D.collection(c.db,`homes/${homeId}/receipts`),D.where('group','==',group))),result=await M.undo(c,homeId,records.docs.map(d=>({id:d.id,data:d.data()})));const r=records.docs[0]?.data();quickUndo={home:homeId,target:r?.target,version:result.state==='review'?state.shop.find(x=>x.id===r?.target)?.version:r.after.version+1,message:result.state==='review'?r.after.name+': el producto ha cambiado después. No se ha deshecho ni sobrescrito ese cambio.':r.after.name+': devuelto a pendiente, falta guardar esta compra en despensa.'};}catch(err){quickUndo={home:homeId,message:errorMessage(err)};}finally{quickBusy.delete(lock);render();}}

function household(){const h=state.home,draft=settingsDraft?.homeId===homeId?settingsDraft:null,owner=h.owner===c.auth.currentUser.uid;const groups=[...new Set(state.receipts.filter(r=>r.actor===c.auth.currentUser.uid&&r.kind!=='undo'&&!r.undoAfter&&r.createdAt&&Date.now()-r.createdAt.toMillis()<30*60000).map(r=>r.group))].filter(g=>!state.receipts.some(r=>r.undoOf===g));return intro('COMPARTIR Y ORGANIZAR',esc(h.name),'Los miembros comparten despensa, compra e historial de operaciones.')+`<div class="grid-two"><section class="panel"><h2>Miembros</h2>${h.members.map(uid=>`<div class="member"><span class="avatar">${esc(h.memberNames[uid]?.slice(0,1))}</span><div><strong>${esc(h.memberNames[uid])}</strong><small class="hint">${uid===h.owner?'Administración':'Miembro'}</small></div>${owner&&uid!==h.owner?`<button class="text-link" data-action="remove" data-id="${uid}">Retirar</button>`:''}</div>`).join('')}${owner?button('invite','Crear invitación','',true):''}<p class="hint">Enlace de un uso, válido siete días. Compártelo solo con la persona que quieres incorporar, incluso si aún no tiene cuenta.</p></section><section class="panel"><h2>Ajustes</h2>${owner?`<form id="settings-form" data-version="${draft?.version??h.version}"><label>Raciones<input id="servings" type="number" min="1" max="12" value="${draft?.servings??h.servings}" required></label><label>Días de aviso<input id="notice" type="number" min="0" max="30" value="${draft?.noticeDays??h.noticeDays}" required></label><label class="checkbox-line"><input id="home-vegetarian" type="checkbox" ${(draft?.vegetarian??h.vegetarian)?'checked':''}>Preferencia vegetariana del hogar</label><details id="home-preferences"><summary>Ingredientes que preferimos excluir</summary><p class="hint">Preferencia compartida del hogar, sin datos de salud. No sirve como protección para alergias.</p><div class="preference-options">${ingredientNames.map((n,index)=>`<label class="checkbox-line"><input id="home-exclude-${index}" type="checkbox" data-home-exclude="${esc(n)}" ${(draft?.excludedIngredients??h.excludedIngredients??[]).includes(n)?"checked":""}>${esc(n)}</label>`).join("")}</div></details><p>Zona horaria: Madrid</p><button class="button secondary">Guardar ajustes</button><p id="settings-error" role="alert"></p>${draft&&draft.version!==h.version?'<p class="notice" role="alert">Los ajustes han cambiado mientras editabas. Revisa los valores actuales antes de guardar.</p><button type="button" class="text-link" id="refresh-settings">Revisar ajustes actuales</button>':''}</form>`:`<p>${ration(h.servings)} · Aviso ${h.noticeDays} días · Madrid</p>`}</section></div><section class="panel"><h2>Corregir una operación reciente</h2><p class="hint">Solo tus operaciones de los últimos 30 minutos. Si otro miembro ha cambiado los lotes, la corrección se detiene para revisión.</p>${groups.map(g=>{const r=state.receipts.find(x=>x.group===g);return `<div class="settings-row"><span>${esc(operationLabels[r.kind]||r.kind)} · ${esc(operationFoods(g))} · ${r.createdAt.toDate().toLocaleTimeString('es')}</span>${button('undo','Revisar corrección',g,true)}</div>`;}).join('')||'<p>Sin operaciones corregibles.</p>'}</section><section class="panel"><h2>Ayuda y privacidad</h2><p>No se recogen alergias ni datos sanitarios. Solo hay perfiles ficticios en <a href="maqueta#hogar">demostración</a>; no protegen frente a alergias reales. Consulta etiquetas y posibles trazas.</p><p>El dictado opcional está disponible en Añadir alimento. Actívalo al pulsar el micrófono, detén la escucha y revisa los datos antes de guardar. Si falla o no está disponible, conserva el formulario manual. La prueba aislada de voz fue confirmada en PC y móvil; la integración requiere sus propias comprobaciones. <a href="voz-prueba.html">Probar dictado con datos ficticios</a>: prueba aislada, sin acceso ni guardado en tu hogar.</p><p><a href="maqueta">Abrir demostración con datos ficticios →</a></p><p class="hint">ud representa piezas enteras, sin decimales. Los lotes existentes no se redondean ni se convierten automáticamente. Si un lote antiguo contiene piezas fraccionarias, revisa su cantidad antes de utilizarlo.</p>${button('logout','Cerrar sesión','',true)}</section>`;}
function render(){const openedDetails=Array.from(document.querySelectorAll('#content details[id][open]')).map(el=>el.id);const focused=document.activeElement,focus=focusKey(focused),draft=focused?.closest('form')&&focused.closest('form').id!=='settings-form'?Array.from(focused.closest('form').querySelectorAll('input,select')).map(el=>({id:el.id,value:el.value,checked:el.checked})):[];if(releaseChanged&&!$('release-warning')){const warning=document.createElement('div');warning.id='release-warning';warning.className='notice';warning.setAttribute('role','alert');warning.innerHTML='<strong>Hay una actualización disponible</strong>Recarga esta página antes de guardar. Tus cambios sin guardar no se conservarán.<button class="button secondary" id="reload-release">Recargar versión</button>';$('connection-status').after(warning);$('reload-release').onclick=()=>location.reload();}page=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'inicio';for(const key of ['desktop-nav','mobile-nav'])$(key).innerHTML=nav.map(([p,icon,label])=>`<a href="#${p}" ${page===p?'aria-current="page"':''}><svg aria-hidden="true"><use href="#i-${icon}"/></svg>${label}</a>`).join('');document.title=nav.find(n=>n[0]===page)[2]+' · Cocina a Tiempo';document.querySelector('.side-footer strong').textContent=state.home?.name||'Mi hogar';document.querySelector('.side-footer small').textContent=state.home?`${state.home.members.length} ${state.home.members.length===1?'miembro':'miembros'}`:'Acceso con correo';const status=releaseChanged?'ACTUALIZACIÓN DISPONIBLE':!navigator.onLine?'SIN CONEXIÓN · GUARDADO BLOQUEADO':state.home?(state.server?'AL DÍA':'ACTUALIZANDO'):'COCINA A TIEMPO';$('connection-status').hidden=status==='AL DÍA'||status==='COCINA A TIEMPO';$('connection-status').textContent=status;if(!c.auth.currentUser)$('content').innerHTML=authView();else if(homeId==='revocado')$('content').innerHTML=intro('ACCESO','Acceso al hogar no disponible','La cuenta ya no tiene acceso o no se puede confirmar la conexión. No se mostrarán datos guardados del hogar.')+button('reload','Volver a comprobar','',true)+button('logout','Cerrar sesión','',true);else if(!homeId)$('content').innerHTML=setupView();else if(!state.home)$('content').innerHTML='<p role="status">Cargando hogar…</p>';else $('content').innerHTML=(!canWrite()?(releaseChanged?'<div class="notice" role="status"><strong>Guardado detenido por actualización</strong>Recarga la versión con el botón de arriba antes de guardar.</div>':'<div class="notice" role="status"><strong>Guardado no disponible</strong>Espera a que se confirme la conexión. No se guardan operaciones sin conexión.</div>'):'')+({inicio:homeView,despensa:pantry,recetas:cooking,compra:shopping,hogar:household}[page])();bind();for(const id of openedDetails){const el=$(id);if(el)el.open=true;}for(const field of draft){const el=$(field.id);if(el){el.value=field.value;if(el.type==='checkbox')el.checked=field.checked;}}if(!$('dialog').open)resolveFocus(focus)?.focus({preventScroll:true});}
function bind(){if($('auth-form')){const authAction=async(register=false)=>{if(authBusy)return;authBusy=true;const email=$('email').value.trim(),password=$('password').value;try{if(register)await U.createUserWithEmailAndPassword(c.auth,email,password);else await U.signInWithEmailAndPassword(c.auth,email,password);}catch(e){if($('auth-message'))$('auth-message').textContent=errorMessage(e);}finally{authBusy=false;}};$('auth-form').onsubmit=e=>{e.preventDefault();authAction();};$('register').onclick=()=>{if($('auth-form').reportValidity())authAction(true);};$('reset').onclick=async()=>{const email=$('email').value.trim();if(!email){$('auth-message').textContent='Escribe primero el correo de tu cuenta.';return;}try{await U.sendPasswordResetEmail(c.auth,email);$('auth-message').textContent='Solicitud completada. Revisa tu correo si existe una cuenta con esa dirección.';}catch(e){$('auth-message').textContent=errorMessage(e);}};}if($('setup-form'))$('setup-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{homeId=inviteToken()?await M.join(c,inviteToken(),$('alias').value):await M.createHome(c,$('home-name').value,$('alias').value);history.replaceState(null,'',location.pathname+(new URL(location.href).searchParams.get('revision')==='ficticia'?'?revision=ficticia':'')+'#inicio');await loadAccount();}catch(err){$('setup-message').textContent=errorMessage(err);b.disabled=false;}};if($('search'))$('search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos);};if($('place-filter'))$('place-filter').onchange=e=>{place=e.target.value;render();};if($('food-filter'))$('food-filter').onchange=e=>{foodFilters.value=e.target.value;render();};if($('minutes'))$('minutes').onchange=e=>{minutes=Number(e.target.value);render();};if($('vegetarian'))$('vegetarian').onchange=e=>{vegetarian=e.target.checked;render();};if($('settings-form')){const form=$('settings-form');form.oninput=()=>{settingsDraft={homeId,version:Number(form.dataset.version),servings:Number($('servings').value),noticeDays:Number($('notice').value),vegetarian:$('home-vegetarian').checked,excludedIngredients:Array.from(form.querySelectorAll('[data-home-exclude]:checked')).map(el=>el.dataset.homeExclude)};};if($('refresh-settings'))$('refresh-settings').onclick=()=>{settingsDraft=null;render();};$('settings-form').onsubmit=async e=>{e.preventDefault();try{if(!canWrite())throw Error('Espera a recuperar la conexión.');await M.settings(c,homeId,{servings:Number($('servings').value),noticeDays:Number($('notice').value),vegetarian:$('home-vegetarian').checked,excludedIngredients:Array.from(form.querySelectorAll('[data-home-exclude]:checked')).map(el=>el.dataset.homeExclude)},Number(form.dataset.version));settingsDraft=null;render();toast('Ajustes actualizados.');}catch(err){$('settings-error').textContent=errorMessage(err);}};}}
function lotForm({lot=null,shop=null}={}){const item=lot||shop,operation={group:M.id(),lotId:lot?.id||M.id()};let saving=false,frozen=null;open(`<h2>${shop?'Guardar compra en despensa':lot?'Editar lote':'Añadir alimento'}</h2>${shop?'<p>Revisa el nombre, la cantidad y la unidad realmente adquiridos, la ubicación y la fecha opcional con su tipo. La compra y el nuevo lote se guardarán juntos, sin duplicar la incorporación.</p>':''}<form id="lot-form" novalidate>${!lot&&!shop?voiceFormHTML():'<p class="hint">El dictado está disponible solo al añadir alimentos. Puedes completar este formulario manualmente.</p>'}<p id="lot-error" role="alert" tabindex="-1"></p><label>Alimento<input id="lot-name" aria-describedby="lot-error food-help" list="food-names" maxlength="60" required value="${esc(item?.name||'')}" ></label><datalist id="food-names">${[...new Set([...recipes.flatMap(r=>r.ingredients.map(i=>i[0])),'Atún fresco','Atún en conserva'])].map(n=>`<option value="${esc(n)}">`).join('')}</datalist><div class="form-grid"><label>Cantidad<input id="lot-qty" aria-describedby="lot-error" type="number" min="0" max="1000000000" step="1" required value="${item?.qty||1}" ></label><label>Unidad<select id="lot-unit" aria-describedby="food-help" >${['ud','g','kg','ml','l'].map(u=>`<option ${u===item?.unit?'selected':''}>${u}</option>`).join('')}</select></label><label>Ubicación<select id="lot-place">${['Nevera','Despensa','Congelador'].map(p=>`<option ${p===lot?.place?'selected':''}>${p}</option>`).join('')}</select></label><label>Fecha opcional<input id="lot-date" aria-describedby="lot-error" type="date" value="${lot?.date||''}"></label></div><label>Tipo<select id="lot-type">${['Caducidad','Consumo preferente'].map(t=>`<option ${t===lot?.dateType?'selected':''}>${t}</option>`).join('')}</select></label><details><summary>Ayuda sobre nombres y unidades</summary><p class="hint">Puedes elegir un nombre o escribir el tuyo. Distingue fresco y conserva. Las piezas no se convierten a peso.</p><p id="food-help" class="hint" role="status"></p></details><div class="dialog-actions"><button class="button coral" id="submit-lot">${shop?'Guardar en despensa':'Revisar lote'}</button>${shop||!lot?'<button type="button" class="button secondary" id="cancel-lot">Cancelar</button>':''}</div></form>`);const help=()=>{const pieces=$('lot-unit').value==='ud';$('lot-qty').step=pieces?'1':'0.001';const name=$('lot-name').value,unit=$('lot-unit').value,reference=recipes.flatMap(r=>r.ingredients).find(([n])=>sameFood(n,name));$('food-help').textContent=P.ambiguous(name)?'Indica Atún fresco o Atún en conserva. Atún sin especificar no cubre ninguna de esas recetas.':reference?`Nombre reconocido para recetas: ${reference[0]}. ${P.unitBase(unit)===P.unitBase(reference[2])?(['kg','l'].includes(unit)?`Conversión exacta: 1 ${unit} = 1000 ${P.unitBase(unit)}.`:'La unidad coincide.'):`Registrado en ${unit}; las recetas usan ${reference[2]}. Podrás confirmar las piezas utilizadas desde la receta o introducir una medida real.`} Las piezas no se convierten a peso. No se modifica otro lote.`:'Se conserva tu nombre. Si no coincide con una receta, no contará como ingrediente disponible. ud = piezas enteras, sin decimales; g/kg = gramos/kilos; ml/l = mililitros/litros. 1 kg = 1000 g; 1 l = 1000 ml.';};$('lot-name').oninput=help;$('lot-unit').onchange=help;help();if(!lot&&!shop)foodVoice=bindFoodVoice($('lot-form'),{onApplied:help});if(shop||!lot)$('cancel-lot').onclick=()=>{if(!saving)$('dialog').close();};$('lot-form').onsubmit=async e=>{e.preventDefault();if(saving)return;if(foodVoice?.active){$('lot-error').textContent='Pulsa Detener y revisa el dictado antes de guardar.';return;}try{const props={name:$('lot-name').value.trim(),qty:Number($('lot-qty').value),unit:$('lot-unit').value,place:$('lot-place').value,date:$('lot-date').value,dateType:$('lot-date').value?$('lot-type').value:''};M.validateLot(props);if(!canWrite())throw Error('No se puede guardar ahora. Conserva estos datos y recupera la conexión o revisa la actualización disponible.');const {group,lotId}=operation;let changes;if(shop){if(!canWrite())throw Error('Guardado no disponible. Recupera la conexión o recarga la versión.');if(frozen&&!M.equal(frozen,props))throw Error('Esta revisión ya se intentó guardar. Cierra y actualiza el producto antes de modificarla.');frozen={...props};saving=true;setFormBusy(true);const result=await M.incorporate(c,homeId,shop.id,raw(shop),props,operation);if(result.state==='review'){$('lot-error').textContent='El producto ha cambiado. No se ha guardado. Cierra el formulario y actualiza la compra antes de revisarlo de nuevo.';$('lot-error').focus();$('submit-lot').disabled=true;return;}$('dialog').close();toast(result.state==='duplicate'?'La compra ya estaba guardada. No se ha creado otro lote.':'Compra guardada en despensa.');return;}else changes=[{type:'lot',id:lotId,before:lot?raw(lot):null,after:lot?{...raw(lot),...props}:M.newLot(props)}];review(`${shop?'Incorporar':'Guardar'} ${esc(props.name)}`,`${fmt(props.qty)} ${props.unit} · ${props.place} · ${props.date||'Fecha desconocida'} ${esc(props.dateType)}`,changes,{group,kind:shop?'incorporate':lot?'edit':'add'});}catch(err){for(const id of ['lot-name','lot-qty','lot-date'])$(id).removeAttribute('aria-invalid');if(!$('lot-name').value.trim())$('lot-name').setAttribute('aria-invalid','true');else if(!(Number($('lot-qty').value)>0&&Number($('lot-qty').value)<=1e9)||($('lot-unit').value==='ud'&&!Number.isInteger(Number($('lot-qty').value))))$('lot-qty').setAttribute('aria-invalid','true');else if(err.message.includes('fecha'))$('lot-date').setAttribute('aria-invalid','true');$('lot-error').textContent=errorMessage(err);$('lot-error').focus();}finally{if(saving){saving=false;setFormBusy(false);if($('lot-error')?.textContent.includes('El producto ha cambiado'))$('submit-lot').disabled=true;}}};function setFormBusy(busy){$('dialog').setAttribute('aria-busy',String(busy));for(const el of $('lot-form').querySelectorAll('input,select,button'))el.disabled=busy;$('close-dialog').disabled=busy;if($('submit-lot'))$('submit-lot').textContent=busy?'Guardando…':shop?'Guardar en despensa':'Revisar lote';}}
function review(title,copy,changes,options){pending={changes,options};open(`<h2>${title}</h2><p>${copy}</p><p class="hint">Si los datos revisados cambian, se detendrá la operación. Si vuelves a intentarlo, la operación no se repetirá.</p><p id="save-message" role="status"></p><div class="dialog-actions"><button class="button coral" id="save-operation">Confirmar y guardar</button><button class="button secondary" id="cancel-operation">Cancelar</button></div>`);$('cancel-operation').onclick=()=>{$('dialog').close();pending=null;};$('save-operation').onclick=async e=>{const p=pending;if(!p)return;e.target.disabled=true;try{if(p.options.kind==='cook'&&(!recipeFresh(recipes.find(r=>r.id===activeRecipe?.key)))){$('save-message').textContent='Las existencias o condiciones han cambiado. No se ha guardado. Cierra la revisión y actualiza la receta.';pending=null;return;}if(!canWrite())throw Error(releaseChanged?'Hay una actualización disponible. Recarga antes de guardar; esta operación no se ha aplicado.':'Sin conexión confirmada. No se ha guardado. Recupera la conexión y vuelve a revisar.');const result=await M.commit(c,homeId,p.changes,p.options);if(result.state==='review'){$('save-message').textContent='Los datos han cambiado. No se ha aplicado esta operación. Cierra esta revisión y comprueba de nuevo las cantidades.';pending=null;return;}$('dialog').close();pending=null;toast(result.state==='duplicate'?'La operación ya estaba guardada. No se ha repetido.':S.operationMessage(p.changes));$('content').classList.add('celebrate');}catch(err){$('save-message').textContent=errorMessage(err);e.target.disabled=false;}};}
const recipeLots=r=>state.lots.filter(l=>r.ingredients.some(([n])=>sameFood(n,l.name))).slice().sort((a,b)=>a.id.localeCompare(b.id));
const recipeFresh=r=>activeRecipe?.key===r.id&&activeRecipe.day===M.today()&&M.equal(recipeLots(r),activeRecipe.snapshot);
function presentMessage(i){const pieces=i.lots.every(l=>l.unit==='ud'),quantity=pieces?`${fmt(M.round(i.lots.reduce((n,l)=>n+l.qty,0)))} unidades de ${i.name.toLocaleLowerCase('es')}`:i.lots.map(l=>`${fmt(l.qty)} ${l.unit} de ${l.name}`).join(', ');return `Tienes ${quantity}; confirma cuánto utilizarás. Referencia: ${fmt(i.qty)} ${i.unit}; no hay equivalencia comprobada.`;}
function proposalText(proposal,i){const compatible=proposal.selected.every(x=>P.unitBase(x.lot.unit)===P.unitBase(i.unit)),amounts=new Map();for(const x of proposal.selected){const unit=compatible?i.unit:x.lot.unit;amounts.set(unit,P.quantityRound((amounts.get(unit)||0)+(compatible?P.convert(x.qty,x.lot.unit,unit):x.qty),unit));}return [...amounts].map(([unit,qty])=>unit==='ud'?`${fmt(qty)} ${esc(i.name.toLocaleLowerCase('es'))}`:`${fmt(qty)} ${unit} de ${esc(i.name.toLocaleLowerCase('es'))}`).join(', ');}
function recipe(key,keep=false,message=''){const r=recipes.find(r=>r.id===key);if(!r?.complete)return;if(!keep||activeRecipe?.key!==key)activeRecipe={key,snapshot:recipeLots(r),day:M.today(),choices:{}};const req=P.requirements(r,recipeServings[key]||state.home.servings,state.lots,M.today()),choices=activeRecipe.choices,unresolved=req.filter(i=>i.state==='pending'&&!choices[foodKey(i.name)]),unmeasured=Object.values(choices).some(x=>x.unmeasured),measuredShort=Object.values(choices).some(x=>!x.unmeasured&&!x.adjustedReference&&!x.sufficient);let canCook=true;try{P.consumption(r,recipeServings[key]||state.home.servings,state.lots,M.today(),choices);}catch{canCook=false;}
open(`<div class="recipe-detail"><div class="recipe-scroll"><h2>${r.name}</h2>${message?`<p role="alert">${esc(message)}</p>`:''}<p>${ration(recipeServings[key]||state.home.servings)} · ${r.time} min</p><label>Raciones de esta receta<select id="recipe-servings">${Array.from({length:12},(_,n)=>n+1).map(n=>`<option ${(recipeServings[key]||state.home.servings)===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="ingredient-status">${req.map((i,index)=>{const choice=choices[foodKey(i.name)],proposal=choice||P.automaticPortion(i,state.lots,M.today()),label=choice?(choice.adjustedReference?'Cantidad adaptada y revisada respecto a la receta':choice.unmeasured?'Confirmado manualmente · suficiencia sin comprobar':choice.sufficient?'Cantidad medida suficiente para la referencia':'Cantidad medida insuficiente'):({sufficient:'Cantidad suficiente',absent:'Ingrediente ausente',insufficient:'Cantidad insuficiente',pending:'Cantidad pendiente de confirmar'}[i.state]);return `<section class="portion-item"><div class="ingredient-line"><h3>${esc(i.name)}</h3>${proposal?`<span class="proposed-use">Se usarán ${proposalText(proposal,i)}.</span>`:''}${i.lots.length?button('portion',proposal?'Cambiar':'Resolver cantidad',String(index),true):''}</div>${!proposal||choice?.unmeasured||choice?.adjustedReference||choice&&!choice.sufficient?`<p class="ingredient-alert">${label}${i.state==='insufficient'&&!choice?` · tienes ${fmt(i.have)} ${i.unit}; faltan ${fmt(i.short)} ${i.unit}`:''}</p>`:''}${i.state==='pending'&&!choice?`<p>${esc(presentMessage(i))}</p>`:''}${!proposal&&i.state==='sufficient'?'<p role="status">Revisa las piezas del lote; no se descuentan fracciones.</p>':''}${proposal?`<details><summary>Lotes y referencia</summary><p>Referencia: ${fmt(i.qty)} ${i.unit}.${choice?.measured?` Medida real: ${fmt(choice.measured.qty)} ${choice.measured.unit}.`:''}</p><p>${proposal.selected.map(x=>`${fmt(x.qty)} ${x.lot.unit} · ${esc(x.lot.place)} · ${x.lot.date?esc(x.lot.date.split('-').reverse().join('/')):'sin fecha'}`).join('; ')}</p></details>`:`<p class="hint">Referencia: ${fmt(i.qty)} ${i.unit}.</p>`}</section>`;}).join('')}</div><p class="hint">Alérgenos de la receta base: ${r.allergens.join(', ')||'no se identifican de los 14 grupos en la base descrita'}. No garantiza seguridad para personas alérgicas.</p><details><summary>Ingredientes, variantes y etiquetas</summary><p class="hint">${esc(r.allergenNotes)}</p><p class="hint">Revisa los ingredientes y posibles trazas de cada marca y evita contaminación cruzada en la preparación. Esta información describe la receta base y no comprueba los productos de tu hogar.</p></details>${r.water?`<p class="hint">Agua: ${M.round(r.water*(recipeServings[key]||state.home.servings)/r.baseServings)} ml orientativos, sin descontar. Aceite y sal sí se comparan.</p>`:''}<h3>Preparación</h3><ol>${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="hint" id="quantity-guidance">${unresolved.length?'Revisa las cantidades pendientes de '+unresolved.map(i=>esc(i.name)).join(', ')+' antes de preparar la compra.':measuredShort?'La cantidad medida es insuficiente. Ajusta la selección o revisa la compra.':unmeasured?(canCook?'Selección lista para revisar el cocinado. La suficiencia en gramos o mililitros sigue sin comprobar.':'Cantidad elegida, con suficiencia sin comprobar. Revisa también los ingredientes ausentes o insuficientes.'):Object.keys(choices).length?'Cantidades seleccionadas y medidas revisadas.':canCook?'Propuesta calculada con los lotes próximos a su fecha. Puedes cambiarla o revisar el cocinado.':'Resuelve las cantidades señaladas antes de cocinar.'}${Object.keys(choices).length?' El descuento solo se realiza al confirmar y guardar el cocinado.':''}</p></div><div class="recipe-actions">${canCook?button('cook','He cocinado',key):''}${button('missing','Revisar ingredientes para Compra',key,true)}</div></div>`);
$('recipe-servings').onchange=e=>{recipeServings[key]=Number(e.target.value);recipe(key);};}
function portion(index){const key=activeRecipe?.key,r=recipes.find(r=>r.id===key);if(!r)return;if(!recipeFresh(r)){recipe(key,false,'Las existencias han cambiado. Revisa las cantidades de nuevo.');return;}const i=P.requirements(r,recipeServings[key]||state.home.servings,state.lots,M.today())[Number(index)],choice=activeRecipe.choices[foodKey(i.name)],measurementUnit=P.unitBase(i.unit),measurementUnits=i.other.length?(measurementUnit==='g'?['g','kg']:measurementUnit==='ml'?['ml','l']:[]):[];i.lots.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));let proposal={};if(!choice&&i.state==='sufficient'){const one={...r,ingredients:[[i.name,i.qty,i.unit]],baseServings:1};for(const x of P.consumption(one,1,state.lots,M.today()).changes)proposal[x.id]=x.used;}
open(`<h2>Cuánto utilizarás de ${esc(i.name)}</h2><p>Referencia de la receta: ${fmt(i.qty)} ${i.unit}. ${i.state==='pending'?esc(presentMessage(i)):'Elige los lotes y las cantidades que utilizarás.'}</p><p>Elegir esta cantidad no cambia tu despensa. El descuento solo ocurre al confirmar y guardar el cocinado.</p><form id="portion-form" novalidate><p id="portion-error" role="alert" tabindex="-1"></p>${i.lots.map((l,n)=>`<label>${esc(l.name)} · ${fmt(l.qty)} ${l.unit} disponibles · ${esc(l.place)} · ${esc(l.date||'sin fecha')}<input id="portion-${n}" aria-describedby="portion-error" type="number" min="0" max="${l.qty}" step="${l.unit==='ud'?'1':'0.001'}" value="${choice?choice.selected.find(x=>x.lot.id===l.id)?.qty||'':proposal[l.id]||''}" placeholder="Cuánto utilizarás (${l.unit})"></label>`).join('')}${measurementUnits.length?`<div class="form-grid"><label>Medida real de la cantidad elegida en otra unidad (opcional)<input id="portion-measure" type="number" min="0" step="0.001" value="${choice?.measured?.qty||''}"></label><label>Unidad de la medida<select id="portion-measure-unit">${measurementUnits.map(u=>`<option ${choice?.measured?.unit===u?'selected':''}>${u}</option>`).join('')}</select></label></div><p class="hint">Pesa o mide solo la cantidad elegida en otra unidad. Se suma a los gramos o mililitros que elijas directamente; no modifica el lote original.</p>`:'<p class="hint">Confirma las cantidades en la unidad original de cada lote. No se inventan equivalencias entre piezas y peso.</p>'}${i.state!=='pending'?`<label class="checkbox-line"><input id="adjust-reference" type="checkbox" ${choice?.adjustedReference?'checked':''}>Usaré menos que la referencia de la receta; he revisado esta adaptación.</label>`:''}<p class="hint">${i.state==="pending"?"Sin medida de las piezas, la suficiencia sigue sin comprobarse. Una medida menor que la referencia se mostrará como insuficiente.":"La cantidad se compara con la referencia. Si usarás menos, confirma la adaptación antes de continuar."}</p><div class="dialog-actions"><button class="button coral">Usaré esta cantidad</button><button type="button" id="portion-back" class="button secondary">Volver a receta</button></div></form>`);
$('portion-form').oninput=e=>{if(e.target.id!=='adjust-reference'&&$('adjust-reference'))$('adjust-reference').checked=false;};$('portion-back').onclick=()=>recipe(key,true);$('portion-form').onsubmit=e=>{e.preventDefault();try{if(!recipeFresh(r))throw Error('Las existencias han cambiado. Vuelve a abrir la receta y revisar los lotes.');const amounts=Object.fromEntries(i.lots.map((l,n)=>[l.id,Number($('portion-'+n).value)])),value=$('portion-measure')?.value,measured=value?{qty:Number(value),unit:$('portion-measure-unit').value}:null;activeRecipe.choices[foodKey(i.name)]=P.confirmPortion(i,state.lots,M.today(),amounts,measured,{adjustReference:!!$("adjust-reference")?.checked});recipe(key,true);}catch(err){$('portion-error').textContent=err.message;$('portion-error').focus();}};}
function cook(key){const r=recipes.find(r=>r.id===key);if(!recipeFresh(r)){recipe(key,false,'Las existencias han cambiado. Revisa de nuevo las cantidades antes de cocinar.');return;}try{const plan=P.consumption(r,recipeServings[key]||state.home.servings,state.lots,M.today(),activeRecipe.choices),copy=plan.changes.map(x=>`${esc(x.before.name)} · ${esc(x.before.place)} · ${esc(x.before.date || 'sin fecha')}: ${fmt(x.used)} ${x.before.unit} · quedarán ${fmt(x.after.qty)} ${x.after.unit}`);review('Revisar cocinado',`${esc(r.name)}<br>${copy.join('<br>')}${plan.warnings.length?'<br><strong>'+plan.warnings.map(esc).join('<br>')+'</strong>':''}`,plan.changes.map(({used,...x})=>x),{group:M.id(),kind:'cook',expectations:recipeLots(r).map(l=>({type:'lot',id:l.id,before:raw(l)}))});}catch(err){recipe(key,true,err.message);}}

const shopId=async(name,unit)=>'item-'+Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(foodKey(name)+'|'+unit))),b=>b.toString(16).padStart(2,'0')).join('');
async function shopChanges(items,increment=false){const changes=[];for(const item of items){const i=S.validateShopping(item),matching=state.shop.filter(s=>sameFood(s.name,i.name)&&P.unitBase(s.unit)===P.unitBase(i.unit)),existing=matching.filter(s=>s.status==='open').sort((a,b)=>a.id.localeCompare(b.id))[0];const unit=existing?.unit||P.unitBase(i.unit),key=existing?.id||await shopId(i.name,unit),snap=await D.getDocFromServer(M.entryRef(c,homeId,'shop',key)),before=snap.exists()?snap.data():null;if(before&&['bought','incorporated'].includes(before.status)){const freshId='pending-'+M.id(),plan=S.shoppingQuantity(i,null,matching.filter(s=>s.status==='bought'),increment);if(!plan.changed)continue;changes.push({type:'shop',id:freshId,before:null,after:{name:i.name,qty:plan.qty,unit:plan.unit,status:'open',lotId:'',createdAt:D.Timestamp.now()}});continue;}const plan=S.shoppingQuantity(i,before,matching.filter(s=>s.status==='bought'),increment);if(!plan.changed)continue;changes.push({type:'shop',id:key,before,after:{name:i.name,qty:plan.qty,unit:plan.unit,status:'open',lotId:'',createdAt:before?.createdAt||D.Timestamp.now()}});}return changes;}
const shopReview=changes=>changes.map(x=>`${esc(x.after.name)}: ${x.before&&x.before.status==='open'?fmt(x.before.qty)+' '+x.before.unit+' pendiente → ':''}${fmt(x.after.qty)} ${x.after.unit} · Pendiente. Lo ya comprado se conserva separado.`).join('<br>');
function shopForm(shop=null){open(`<h2>${shop?'Editar producto de Compra':'Añadir a la compra'}</h2><form id="shop-form" novalidate><p id="shop-error" role="alert" tabindex="-1"></p><label>Producto<input id="shop-name" required maxlength="60" value="${esc(shop?.name||'')}"></label><div class="form-grid"><label>Cantidad<input id="shop-qty" type="number" min="${(!shop||shop.unit==='ud')?1:0.001}" max="1000000000" step="${(!shop||shop.unit==='ud')?1:0.001}" required value="${shop?.qty||1}"></label><label>Unidad<select id="shop-unit">${['ud','g','kg','ml','l'].map(u=>`<option ${u===shop?.unit?'selected':''}>${u}</option>`).join('')}</select></label></div>${shop?'<p class="hint">Editar lo comprado conserva su estado. Para pedir más, usa Añadir producto: quedará pendiente.</p>':''}<button class="button coral">Revisar producto</button></form>`);const syncShopUnit=()=>{const pieces=$('shop-unit').value==='ud';$('shop-qty').min=pieces?'1':'0.001';$('shop-qty').step=pieces?'1':'0.001';};$('shop-unit').onchange=syncShopUnit;syncShopUnit();$('shop-form').onsubmit=async e=>{e.preventDefault();try{const item=S.validateShopping({name:$('shop-name').value,qty:Number($('shop-qty').value),unit:$('shop-unit').value}),changes=shop?[{type:'shop',id:shop.id,before:raw(shop),after:{...raw(shop),...item}}]:await shopChanges([item],true);if(!changes.length)throw Error('No hay cambios que guardar.');review(shop?'Editar producto':'Añadir producto',shop?`${esc(shop.name)} · ${fmt(shop.qty)} ${shop.unit} → ${esc(item.name)} · ${fmt(item.qty)} ${item.unit} · ${shopLabels[shop.status]}`:shopReview(changes),changes,{kind:'shopping',group:M.id()});}catch(err){$('shop-error').textContent=errorMessage(err);$('shop-name').setAttribute('aria-invalid',String(!$('shop-name').value.trim()));$('shop-error').focus();}};}
document.addEventListener('change',async e=>{if(e.target.dataset.exclude){e.target.checked?excluded.add(e.target.dataset.exclude):excluded.delete(e.target.dataset.exclude);render();return;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action:a,id:key}=b.dataset;try{if(a==='logout'){stop?.();stop=null;await U.signOut(c.auth);return;}if(a==='reload'){await loadAccount();return;}if(!state.home)return;if(a==='pending-recipes'){recipeTab='pending';location.hash='recetas';render();return;}if(a==='portion'){portion(key);return;}if(a==='alternatives'){recipeTab='missing';minutes=60;vegetarian=!!state.home.vegetarian;location.hash='recetas';render();return;}if(a==='review-filters'){const details=$('recipe-preferences');if(details){details.open=true;details.querySelector('summary').focus();}else{location.hash='recetas';render();$('recipe-preferences').open=true;$('recipe-preferences').querySelector('summary').focus();}return;}if(a==='clear-filters'){minutes=60;vegetarian=false;excluded.clear();render();return;}if(a==='near'){search='';place='Todas';foodFilters.value='near';location.hash='despensa';render();return;}if(a==='expired'){const filters=S.expiredFilters();search=filters.search;place=filters.place;foodFilters.value=filters.value;location.hash='despensa';render();return;}if(a==='tab'){recipeTab=key;render();return;}if(a==='recipe'){recipe(key);return;}if(a==='add'){lotForm();return;}if(a==='edit'){lotForm({lot:state.lots.find(l=>l.id===key)});return;}if(a==='shop-bought'){await markBought(key);return;}if(a==='quick-undo'){await undoMarked(key);return;}if(a==='incorporate'){if(quickBusy.has(key))return;lotForm({shop:state.shop.find(s=>s.id===key)});return;}if(a==='cook'){cook(key);return;}if(a==='missing'){const r=recipes.find(r=>r.id===key);if(!recipeFresh(r)){recipe(key,false,'Las existencias han cambiado. Revisa otra vez las cantidades.');return;}let items;try{items=P.purchase(r,recipeServings[key]||state.home.servings,state.lots,M.today(),activeRecipe.choices);}catch(err){recipe(key,true,err.message);return;}const changes=await shopChanges(items);if(!changes.length){recipe(key,true,items.length?'Los productos ya están en la compra.':'No hay ingredientes ausentes o insuficientes para añadir.');return;}review('Añadir ingredientes que faltan',shopReview(changes),changes,{kind:'shopping',group:M.id()});return;}if(a==='out'){const l=state.lots.find(l=>l.id===key);open(`<h2>Registrar consumo o descarte de ${esc(l.name)}</h2><form id="out-form"><label>Motivo<select id="reason"><option value="consume">Consumido directamente</option><option value="discard">Desechado</option><option value="cook">Utilizado al cocinar</option></select></label><label>Cantidad (${l.unit})<input id="out-qty" type="number" min="${l.unit==='ud'?1:0.001}" max="${l.qty}" step="${l.unit==='ud'?1:0.001}" value="${l.qty}" required></label><button class="button coral">Revisar consumo o descarte</button></form>`);$('out-form').onsubmit=e=>{e.preventDefault();const n=Number($('out-qty').value),kind=$('reason').value;if(!(n>0&&n<=l.qty))return;try{P.validatePieces(n,l.unit);P.validatePieces(l.qty-n,l.unit);}catch(err){toast(err.message);return;}review('Confirmar consumo o descarte',`${esc(l.name)}: ${fmt(n)} ${l.unit} · ${operationLabels[kind]}. Quedarán ${fmt(P.quantityRound(l.qty-n,l.unit))} ${l.unit}.`,[{type:'lot',id:l.id,before:raw(l),after:{...raw(l),qty:P.quantityRound(l.qty-n,l.unit)}}],{kind,group:M.id()});};return;}if(a==='shop-add'){shopForm();return;}if(a==='shop-edit'){shopForm(state.shop.find(s=>s.id===key));return;}if(a==='shop-remove'){const s=state.shop.find(s=>s.id===key);review('Retirar de la compra',esc(s.name),[{type:'shop',id:s.id,before:raw(s),after:{...raw(s),status:'removed'}}],{kind:'shopping',group:M.id()});return;}if(a==='invite'){if(!canWrite())throw Error('Necesitas conexión para crear la invitación.');const token=await M.invitation(c,homeId),url=location.origin+'/app?invita='+token;open(`<h2>Invitación creada</h2><p>Un uso · siete días. La persona puede registrarse después de abrir el enlace.</p><label>Enlace para compartir<input readonly value="${esc(url)}"></label><p class="hint">Quien tenga este enlace podrá entrar al hogar. Compártelo directamente con la persona invitada.</p>`);return;}if(a==='remove'){open(`<h2>Retirar a ${esc(state.home.memberNames[key])}</h2><p>Perderá el acceso a los lotes, la compra y el historial del hogar.</p><button class="button coral" id="remove-member">Confirmar retirada</button>`);$('remove-member').onclick=async e=>{e.target.disabled=true;try{if(!canWrite())throw Error('Espera a recuperar la conexión.');await M.removeMember(c,homeId,key);$('dialog').close();toast('Miembro retirado.');}catch(err){toast(errorMessage(err));e.target.disabled=false;}};return;}if(a==='undo'){const receiptDocs=await D.getDocs(D.query(D.collection(c.db,`homes/${homeId}/receipts`),D.where('group','==',key)));const list=receiptDocs.docs.map(d=>d.data());if(list.some(r=>r.actor!==c.auth.currentUser.uid||r.kind==='undo'||Date.now()-r.createdAt.toMillis()>=30*60000))throw Error('Solo puedes corregir tus operaciones de los últimos 30 minutos.');const changes=list.map(r=>({type:r.type,id:r.target,before:r.after,after:r.before??{...r.after,...(r.type==='lot'?{qty:0}:{status:'removed'})}}));review('Corregir operación reciente',`${list.map(r=>`${esc(r.after.name)}: ${fmt(r.after.qty)+' '+r.after.unit+(r.type==='shop'?' · '+shopLabels[r.after.status]:'')} → ${r.before?(fmt(r.before.qty)+' '+r.before.unit+(r.type==='shop'?' · '+shopLabels[r.before.status]:'')):(r.type==='lot'?'0 '+r.after.unit:'retirado')}`).join('<br>')}<br>Si alguno cambió después, no se aplicará la corrección.`,changes,{group:'undo-'+key,kind:'undo',undoOf:key});return;}}catch(err){toast(errorMessage(err));}});
