async function checkRelease(){try{const response=await fetch('/release.json',{cache:'no-store'});if(!response.ok)return;const current=await response.json();if(current.release!==APP_RELEASE){releaseChanged=true;render();}}catch{}}
setInterval(checkRelease,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkRelease();});checkRelease();





